window.AUTH=window.AUTH||{};window.AUTH["23-334"]={"d":"23-334","id":"2023/23-334","n":"Department of State v. Munoz","briefs":[{"k":"petitioner","label":"Brief of petitioners Department of State, et al.","date":"2024-02-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-334/300976/20240220181935001_23-334tsUnitedStates.pdf","side":"pet","n":109},{"k":"respondent","label":"Brief of respondents Sandra Muñoz, et al.","date":"2024-03-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-334/305620/20240321140013833_Merit%20Br.%20for%20Respondents.pdf","side":"res","n":140},{"k":"reply","label":"Reply of petitioners Department of State, et al.","date":"2024-04-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-334/307437/20240412110926112_23-334rbUnitedStates.pdf","side":"pet","n":54}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r46_gfbi.pdf","tr":true,"items":[{"t":"case","label":"Agency for Int’l Dev. v. Alliance for Open Soc’y Int’l, Inc.","cite":"140 S. Ct. 2082","y":2020,"id":"2019/19-177","sc":1,"by":{"0":"25","1":"29"}},{"t":"case","label":"Agosto v. INS","cite":"436 U.S. 748","y":1978,"id":"1977/76-1410","sc":1,"by":{"0":"28"}},{"t":"case","label":"Baaghil v. Miller","cite":"1 F.4th 427","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/427/","by":{"0":"20, 26, 31","2":"4, 16"},"q":[{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"even if we take [the right to marriage] as a given, the argument fails because the consulate provided a facially legitimate reason for the visa denials.","cite":"1 F. 4th 427, 434"}]},{"t":"case","label":"Bakran v. Secretary, United States Dep’t of Homeland Sec.","cite":"894 F.3d 557","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/894/557/","by":{"0":"26"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"0":"2"}},{"t":"case","label":"Bright v. Parra","cite":"919 F.2d 31","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/919/31/","by":{"0":"26"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"by":{"0":"16","1":"15","2":"5"},"q":[{"src":"brief","b":2,"text":"an alien who has never presented himself at the borders of this country may avail himself of the [APA] action by bringing the action from abroad.","cite":"352 U.S. 180, 184 n.3"}]},{"t":"case","label":"Burrafato v. United States Dep’t of State","cite":"523 F.2d 554","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/523/554/","by":{"0":"26"}},{"t":"case","label":"Bustamante v. Mukasey","cite":"531 F.3d 1059","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1059/","by":{"0":"10, 21"}},{"t":"case","label":"CIA v. Sims","cite":"471 U.S. 159","y":1985,"id":"1984/83-1075","sc":1,"by":{"0":"44"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"by":{"0":"46"}},{"t":"case","label":"Cleveland Bd. of Educ. v. LaFleur","cite":"414 U.S. 632","y":1974,"id":"1973/72-777","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"matters of marriage and family life.","cite":"414 U.S. 632, 639"}]},{"t":"case","label":"Colindres v. United States Dep’t of State","cite":"71 F.4th 1018","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/71/1018/","by":{"0":"26, 35","1":"51"},"q":[{"src":"brief","b":0,"text":"a factual predicate for denying a visa: The alien must ‘seek[] to enter the United States to engage . . . [in] unlawful activity.’","cite":"71 F.4th at 1024"}]},{"t":"case","label":"DHS v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"by":{"0":"17, 24","1":"16"},"q":[{"src":"brief","b":0,"text":"the power to set the procedures to be followed in determining whether an alien should be admitted.","cite":"140 S. Ct. 1959, 1982"}]},{"t":"case","label":"Del Valle v. Secretary of State","cite":"16 F.4th 832","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/16/832/","by":{"0":"26"}},{"t":"case","label":"Din v. Kerry","cite":"718 F.3d 856","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/718/856/","by":{"0":"6, 40"},"q":[{"src":"brief","b":0,"text":"allege what it believes [Din’s husband] did that would render him inadmissible","cite":"718 F.3d 856, 863"}]},{"t":"case","label":"District Attorney’s Office for the Third Judicial Dist. v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"[p]rocess is not an end in itself,","cite":"557 U.S. 52, 67"}]},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"by":{"0":"23, 25, 40","1":"39, 41","2":"6"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"the Nation's sovereign power to admit or exclude foreigners.","cite":"430 U. S., at 795, n. 6"},{"src":"argument","who":"Mr. Lee","text":"Hawaii type situation or the Mandel type, where Congress has expressly granted to the executive branch a -- a discretionary ability to deny or grant some benefit or -- or in the case of Fiallo and Bell type situation, where that was a substantive direct challenge to a broad congressional policy choice."}]},{"t":"case","label":"Freeman v. United States","cite":"564 U.S. 522","y":2011,"id":"2010/09-10245","sc":1,"by":{"0":"34"}},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"by":{"0":"13, 24","2":"8"},"q":[{"src":"brief","b":0,"text":"not merely ‘a page of history,’ but a whole volume.","cite":"347 U.S. 522, 531"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"not merely `a page of history,' but a whole volume.","cite":"347 U. S. 522, 531"}]},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"chide[d] people for treating judicial opinions as if they were statutes, divorcing a passing comment from its context, ignoring all that came before and after, and treating an isolated phrase as if it were controlling.","cite":"139 S. Ct. 2116, 2139"}]},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"17, 25","1":"16"},"q":[{"src":"brief","b":0,"text":"remains one ‘solely for the responsibility of the Congress and wholly outside the power of this Court to control.’","cite":"342 U.S. at 597"}]},{"t":"case","label":"Hughes v. United States","cite":"584 U.S. 675","y":2018,"id":"2017/17-155","sc":1,"by":{"0":"34","1":"50"}},{"t":"case","label":"Kerry v. Din","cite":"576 U.S. 88","y":2015,"id":"2014/13-1402","sc":1,"by":{"0":"5-7, 14, 15, 27, 28, 31-37, 39, 40, 45, 46","1":"9, 14, 22, 23, 29, 38, 46, 49-51","2":"2, 3, 10-12, 15-17, 19, 20"},"q":[{"src":"brief","b":0,"text":"[T]he Federal Government here has not attempted to forbid a marriage.","cite":"576 U.S. at 94"},{"src":"brief","b":0,"text":"[n]either [Muñoz’s] right to live with her spouse nor her right to live within this country is implicated here.","cite":"576 U.S. at 101"},{"src":"brief","b":2,"text":"the Government is not prohibited from offering more details when it sees fit.","cite":"576 U.S. at 106"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"it enacted a complicated web of regulations that erected serious impediments to a person's ability to bring a spouse into the United States.","cite":"576 U. S., at 96"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"once all the quota spots were flled for the year, the spouse was barred without exception.","cite":"576 U. S., at 97"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"a matter of Page Proof Pending Publication legislative grace rather than fundamental right.","cite":"576 U. S., at 97"}]},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"by":{"0":"4, 5, 13, 14, 16, 17, 20, 31-34","1":"14, 20, 37-42, 47-49, 51, 52","2":"1, 3, 5, 15, 17"},"q":[{"src":"brief","b":0,"text":"inherent in sovereignty, necessary for maintaining normal international relations and defending the country against foreign encroachments and dangers.","cite":"408 U.S. at 765"},{"src":"brief","b":0,"text":"facially legitimate and bona fide reason","cite":"408 U.S. at 770"},{"src":"brief","b":1,"text":"when the Executive exercises this power negatively on the basis of a facially legitimate and bona fide reason, the courts will neither look behind the exercise of that discretion, nor test it by balancing its justification against the First Amendment interests of those who seek personal communication with the applicant.","cite":"408 U.S. at 770"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"constitutional right of entry to this country as a nonimmigrant or otherwise.","cite":"408 U. S., at 762"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[T]he Court's general reaffrmations of this principle have been legion.","cite":"408 U. S., at 765"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"the strength of the audience's interest against that of the Government in refusing a waiver to the particular [noncitizen] applicant, according to some as yet undetermined standard,","cite":"408 U. S., at 768"}]},{"t":"case","label":"Landon v. Plasencia","cite":"459 U.S. 21","y":1982,"id":"1982/81-129","sc":1,"by":{"0":"18","1":"14, 21"},"q":[{"src":"brief","b":1,"text":"a right that ranks high among the interests of the individual.","cite":"459 U.S. at 34"}]},{"t":"case","label":"Lehr v. Robertson","cite":"463 U.S. 248","y":1983,"id":"1982/81-1756","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"with a determination of the precise nature of the private interest that is threatened by the State.","cite":"463 U.S. 248, 256"}]},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"by":{"0":"34"}},{"t":"case","label":"Morales-Izquierdo v. DHS","cite":"600 F.3d 1076","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/600/1076/","by":{"0":"30"}},{"t":"case","label":"National Pork Producers Council v. Ross","cite":"598 U.S. 356","y":2023,"id":"2022/21-468","sc":1,"by":{"0":"36"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"by":{"0":"2"}},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"by":{"0":"17, 24","1":"16"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Ctr.","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"by":{"0":"14, 28-30","1":"30-34","2":"12, 13"},"q":[{"src":"brief","b":0,"text":"action that is directed against a third party and affects the citizen only indirectly or incidentally.","cite":"447 U.S. 773, 788"},{"src":"brief","b":0,"text":"the due process provision of the Fifth Amendment does not apply to the indirect adverse effects of governmental action.","cite":"447 U.S. at 789"},{"src":"brief","b":1,"text":"a strong financial incentive to contest its enforcement decision.","cite":"447 U.S. at 789 n.22"},{"src":"brief","b":2,"text":"the due process provision of the Fifth Amendment does not apply to the indirect adverse effects of governmental action.","cite":"447 U.S. 773, 789"}]},{"t":"case","label":"Obergefell v. Hodges","cite":"576 U.S. 644","y":2015,"id":"2014/14-556","sc":1,"by":{"0":"10, 26, 27","1":"19"},"q":[{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"The right to marry is fundamental as a matter of history and tradition.","cite":"576 U. S. 644, 671"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"marriage is a right `older than the Bill of Rights.'","cite":"576 U. S., at 666, 678"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`[t]here is certainly no country in the world where the tie of marriage is so much respected as in America.'","cite":"576 U. S., at 669"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"assurance that while both still live there will be someone to care for the other","cite":"576 U. S., at 667"},{"src":"argument","who":"Justice Sotomayor","text":"In United States versus Windsor, we said \"marriage is more than a routine classification for purposes of certain statutory benefits.\" So -- and Obergefell, I'm not going to cite it, but it said something to that effect."}]},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"by":{"0":"17","1":"16"}},{"t":"case","label":"Pak v. Biden","cite":"91 F.4th 896","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/91/896/","by":{"0":"31, 37"}},{"t":"case","label":"Payne-Barahona v. Gonzáles","cite":"474 F.3d 1","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/474/1/","by":{"0":"30","2":"13"},"q":[{"src":"brief","b":0,"text":"also have a constitutional right to object to a [spouse’s] being sent to prison.","cite":"474 F.3d 1, 3"}]},{"t":"case","label":"Saavedra Bruno v. Albright","cite":"197 F.3d 1153","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/197/1153/","by":{"0":"4, 23","1":"17","2":"4, 5"}},{"t":"case","label":"Scialabba v. Cuellar de Osorio","cite":"573 U.S. 41","y":2014,"id":"2013/12-930","sc":1,"by":{"0":"2, 3, 22"},"q":[{"src":"brief","b":0,"text":"requires an alien to demonstrate in various ways her admissibility to the United States.","cite":"573 U.S. at 48"}]},{"t":"case","label":"Sesay v. United States","cite":"984 F.3d 312","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/984/312/","by":{"0":"26"}},{"t":"case","label":"Shaughnessy v. United States ex rel. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"by":{"0":"18","1":"16"}},{"t":"case","label":"Silverman v. Rogers","cite":"437 F.2d 102","y":1970,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/437/102/","by":{"0":"26"}},{"t":"case","label":"Swartz v. Rogers","cite":"254 F.2d 338","y":1958,"url":"https://www.courtlistener.com/c/F.2d/254/338/","by":{"0":"26"}},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"by":{"0":"28","2":"6, 13"},"q":[{"src":"brief","b":0,"text":"simple distinction between government action that directly affects a citizen’s legal rights . . . and action that is directed against a third party and affects the citizen only indirectly or incidentally.","cite":"545 U.S. 748, 767"},{"src":"brief","b":2,"text":"more than a unilateral expectation of it. He must, instead, have a legitimate claim of entitlement to it.","cite":"545 U.S. 748, 756"},{"src":"argument","who":"Mr. Gannon","text":"As Justice Kennedy's concurring opinion pointed out, we give the examples of the prisoner who was not able to challenge a transfer to a different prison, the soldier who is not able to challenge a military deployment, in Castle Rock, where the Court relied on O'Bannon, that was an instance --"}]},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"by":{"0":"5, 15, 16, 19, 31-33, 37","1":"13, 14, 39, 50","2":"5, 16-18"},"q":[{"src":"brief","b":0,"text":"reiterated * * * that the Government need provide only a statutory citation to explain a visa denial.","cite":"585 U.S. 667, 703"},{"src":"brief","b":0,"text":"[A]lthough foreign nationals seeking admission have no constitutional right to entry, this Court has engaged in a circumscribed judicial inquiry when the denial of a visa allegedly burdens the constitutional rights of a U.S. citizen.","cite":"585 U.S. at 703"},{"src":"brief","b":2,"text":"opinions have reaffirmed and applied [Mandel’s] deferential standard of review across different contexts and constitutional claims.","cite":"585 U.S. at 703"},{"src":"brief","b":2,"text":"‘respect for the political branches’ broad power over the creation and administration of the immigration system’ meant [in Din] that the Government need provide only a statutory citation to explain a visa denial.","cite":"585 U.S. at 703"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"For more than a century, this Court has recognized that the admission and exclusion of foreign nationals is a `fundamental sovereign attribute exercised by the Government's political departments largely immune from judicial control.'","cite":"585 U. S., at 702"},{"src":"argument","who":"Justice Kagan","text":"But I think that that's a harder and harder argument to make after Trump v. Hawaii, which pretty clearly talks about Mandel as setting forth a very limited but still existent way to review these decisions."},{"src":"argument","who":"Mr. Gannon","text":"To the extent that Trump against Hawaii addressed this, it didn't address -- it assumed without deciding that consular nonreviewability existed and it said that it -- it quoted with approval Justice Kennedy's approach in Din of saying that a statutory citation would be enough in this context."},{"src":"argument","who":"Justice Kagan","text":"I mean, Trump says it's enough."}]},{"t":"case","label":"United States v. Chemical Found.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"by":{"0":"33"}},{"t":"case","label":"United States v. Curtiss-Wright Exp. Corp.","cite":"299 U.S. 304","y":1936,"id":"1900-1940/299us304","sc":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Duvall","cite":"740 F.3d 604","y":2013,"court":"D.C. Cir","url":"https://www.courtlistener.com/c/F.3d/740/604/","by":{"0":"34"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"by":{"0":"5, 12, 13, 17, 25","1":"16","2":"3"},"q":[{"src":"brief","b":0,"text":"[w]hatever the procedure authorized by Congress is, it is due process as far as an alien denied entry is concerned.","cite":"338 U.S. 537, 544"},{"src":"brief","b":2,"text":"[w]hatever the procedure authorized by Congress is, it is due process as far as an alien denied entry is concerned.","cite":"338 U.S. 537, 544"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"Once the government was required to justify its exclusion decision with substantial and reliable evidence, in an open proceeding, Knauff gained admission into the United States.","cite":"338 U. S., at 539"}]},{"t":"case","label":"United States ex rel. London v. Phelps","cite":"22 F.2d 288","y":1927,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/22/288/","by":{"0":"16"}},{"t":"case","label":"United States ex rel. Ulrich v. Kellogg","cite":"30 F.2d 984","y":1929,"url":"https://www.courtlistener.com/c/F.2d/30/984/","by":{"0":"16"}},{"t":"case","label":"United States v. Hernandez-Villanueva","cite":"473 F.3d 118","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/473/118/","by":{"0":"8"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"the ‘liberty’ specially protected by the Due Process Clause includes the right[] to marry.","cite":"521 U.S. 702, 720"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"`deeply rooted in this Nation's history and tradition.'","cite":"521 U. S. 702, 720–721"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`careful [a] description of the asserted fundamental liberty interest.'","cite":"521 U. S. 702, 721"},{"src":"argument","who":"Mr. Gannon","text":"This particular basis for inadmissibility needs to be based on an advisory opinion from Washington, D.C. And so there are lots of other ways in which the State Department can be asked to go back and approve this decision."},{"src":"argument","who":"Mr. Lee","text":"That was a couple that was married in Washington, D.C., and the anti-miscegenation statute in the Commonwealth of Virginia prohibited them from living together as man and wife."},{"src":"argument","who":"Mr. Lee","text":"And -- and I think the Court has addressed a similar context in the prison-type cases, Vitek against Jones, Harper against Washington, where the Court recognized an underlying substantive constitutional interest, for example, in not being forced to take psychotropic drugs or not being removed to a mental facility, and yet it -- the way it balanced those interests was by providing a minimal level of procedural due process."}]},{"t":"case","label":"Wilkinson v. Austin","cite":"545 U.S. 209","y":2005,"id":"2004/04-495","sc":1,"by":{"0":"13, 21, 23","1":"42, 44","2":"5"},"q":[{"src":"brief","b":0,"text":"guarantees implicit in the word ‘liberty.’","cite":"545 U.S. 209, 221"},{"src":"brief","b":0,"text":"must establish that one of these interests is at stake.","cite":"545 U.S. 209, 221"},{"src":"brief","b":1,"text":"the most important procedural mechanisms for purposes of avoiding erroneous deprivations.","cite":"545 U.S. at 226"}]},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"by":{"0":"18, 24","1":"16","2":"3"},"q":[{"src":"brief","b":0,"text":"a class forbidden to enter the United States.","cite":"163 U.S. 228, 233"}]},{"t":"case","label":"Yafai v. Pompeo","cite":"912 F.3d 1018","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/1018/","by":{"0":"26","2":"2, 16"},"q":[{"src":"brief","b":2,"text":"[T]he doctrine of consular nonreviewability bars judicial review of visa decisions made by consular officials abroad.","cite":"912 F.3d 1018, 1020"}]},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"by":{"0":"39"}},{"t":"const","label":"Amendment V, Section 5","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"19"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"38"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/5083","by":{"0":"41"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(9)","(a)(16)"],"by":{"0":"2, 2, 3, 3","2":"3"}},{"t":"usc","label":"8 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/8/1104","subs":["(a)(1)"],"by":{"0":"5","1":"17"}},{"t":"usc","label":"8 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/8/1105","subs":["(a)"],"by":{"0":"43"}},{"t":"usc","label":"8 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/8/1151","subs":["(b)(2)(A)(1)","(d)","(b)(2)(A)(i)","(c)"],"by":{"0":"2, 22","1":"25, 25"}},{"t":"usc","label":"8 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/8/1153","subs":["(b)","(a)(2)"],"by":{"0":"22","2":"14"}},{"t":"usc","label":"8 U.S.C. § 1154","url":"https://www.law.cornell.edu/uscode/text/8/1154","subs":["(a)","(a)(1)","(a)(1)(A)","(b)","(a)(1)(A)(i)"],"by":{"0":"22, 21, 2, 3, 22","1":"3"}},{"t":"usc","label":"8 U.S.C. § 1181","url":"https://www.law.cornell.edu/uscode/text/8/1181","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(2)","(a)(3)","(a)(3)(A)(i)","(a)(3)(A)(ii)","(a)(3)(B)","(a)(3)(B)(i)(II)","(a)(7)","(b)","(b)(1)","(b)(3)","(a)(2)(D)","(a)(2)(I)(i)","(a)(3)(A)","(a)(9)(B)(v)","(a)(3)(B)(i)(IV)(bb)","(a)(3)(B)(i)(VIII)","(a)(3)(B)(iii)(I)","(a)(3)(B)(iv)(VI)(cc)","(a)(3)(B)(iv)(VI)(dd)","(a)(9)(B)(i)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 47, 2, 22, 37, 4, 38, 40, 3, 4, 33, 38, 40, 41, 4, 4, 7, 9, 10, 12, 14, 29, 31, 32, 35, 39, 41, 42, 35, 35, 2, 4, 4, 4, 15, 31","1":"6, 46, 47, 48, 48, 6, 46, 47, 48, 6, 26, 1, 7-9, 11, 17, 37, 41, 43-49, 50-52, 9, 50, 51, 4, 16, 27, 31, 29, 38, 46","2":"6, 20, 1, 15, 17-19, 17-19, 18, 18, 18, 18, 19, 7, 7, 20, 19, 20"},"q":[{"src":"brief","b":0,"text":"[c]lasses of aliens ineligible for visas or admission","cite":"8 U.S.C. 1182(a)"},{"src":"brief","b":0,"text":"provide the alien with a timely written notice that * * * (A) states the determination, and (B) lists the specific provision or provisions of law under which the alien is inadmissible.","cite":"8 U.S.C. 1182(b)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","subs":["(a)","(a)(1)","(d)","(g)","(i)","(a)(1)(A)"],"stext":{"head":"§1201. Issuance of visas","paras":[[0,"(a) Immigrants; nonimmigrants"],[0,"(1) Under the conditions hereinafter prescribed and subject to the limitations prescribed in this chapter or regulations issued thereunder, a consular officer may issue"],[1,"(A) to an immigrant who has made proper application therefor, an immigrant visa which shall consist of the application provided for in section 1202 of this title, visaed by such consular officer, and shall specify the foreign state, if any, to which the immigrant is charged, the immigrant's particular status under such foreign state, the preference, immediate relative, or special immigrant classification to which the alien is charged, the date on which the validity of the visa shall expire, and such additional information as may be required; and"],[1,"(B) to a nonimmigrant who has made proper application therefor, a nonimmigrant visa, which shall specify the classification under section 1101(a)(15) of this title of the nonimmigrant, the period during which the nonimmigrant visa shall be valid, and such additional information as may be required."],[0,"(2) The Secretary of State shall provide to the Service an electronic version of the visa file of each alien who has been issued a visa to ensure that the data in that visa file is available to immigration inspectors at the United States ports of entry before the arrival of the alien at such a port of entry."],[0,"(b) Registration; photographs; waiver of requirement"],[0,"Each alien who applies for a visa shall be registered in connection with his application, and shall furnish copies of his photograph signed by him for such use as may be by regulations required. The requirements of this subsection may be waived in the discretion of the Secretary of State in the case of any alien who is within that class of nonimmigrants enumerated in sections 1101(a)(15)(A), and 1101(a)(15)(G) of this title, or in the case of any alien who is granted a diplomatic visa on a diplomatic passport or on the equivalent thereof."],[0,"(c) Period of validity; renewal or replacement"],[0,"(1) Immigrant visas"],[1,"An immigrant visa shall be valid for such period, not exceeding six months, as shall be by regulations prescribed, except that any visa issued to a child lawfully adopted by a United States citizen and spouse while such citizen is serving abroad in the United States Armed Forces, or is employed abroad by the United States Government, or is temporarily abroad on business, shall be valid until such time, for a period not to exceed three years, as the adoptive citizen parent returns to the United States in due course of his service, employment, or business."],[0,"(2) Nonimmigrant visas"],[1,"A nonimmigrant visa shall be valid for such periods as shall be by regulations prescribed. In prescribing the period of validity of a nonimmigrant visa in the case of nationals of any foreign country who are eligible for such visas, the Secretary of State shall, insofar as practicable, accord to such nationals the same treatment upon a reciprocal basis as such foreign country accords to nationals of the United States who are within a similar class; except that in the case of aliens who are nationals of a foreign country and who either are granted refugee status and firmly resettled in another foreign country or are granted permanent residence and residing in another foreign country, the Secretary of State may prescribe the period of validity of such a visa based upon the treatment granted by that other foreign country to alien refugees and permanent residents, respectively, in the United States."],[0,"(3) Visa replacement"],[1,"An immigrant visa may be replaced under the original number during the fiscal year in which the original visa was issued for an immigrant who establishes to the satisfaction of the consular officer that the immigrant—"],[2,"(A) was unable to use the original immigrant visa during the period of its validity because of reasons beyond his control and for which he was not responsible;"],[2,"(B) is found by a consular officer to be eligible for an immigrant visa; and"],[2,"(C) pays again the statutory fees for an application and an immigrant visa."],[0,"(4) Fee waiver"],[1,"If an immigrant visa was issued, on or after March 27, 2013, for a child who has been lawfully adopted, or who is coming to the United States to be adopted, by a United States citizen, any statutory immigrant visa fees relating to a renewal or replacement of such visa may be waived or, if already paid, may be refunded upon request, subject to such criteria as the Secretary of State may prescribe, if—"],[2,"(A) the immigrant child was unable to use the original immigrant visa during the period of its validity as a direct result of extraordinary circumstances, including the denial of an exit permit; and"],[2,"(B) if such inability was attributable to factors beyond the control of the adopting parent or parents and of the immigrant."],[0,"(d) Physical examination"],[0,"Prior to the issuance of an immigrant visa to any alien, the consular officer shall require such alien to submit to a physical and mental examination in accordance with such regulations as may be prescribed. Prior to the issuance of a nonimmigrant visa to any alien, the consular officer may require such alien to submit to a physical or mental examination, or both, if in his opinion such examination is necessary to ascertain whether such alien is eligible to receive a visa."],[0,"(e) Surrender of visa"],[0,"Each immigrant shall surrender his immigrant visa to the immigration officer at the port of entry, who shall endorse on the visa the date and the port of arrival, the identity of the vessel or other means of transportation by which the immigrant arrived, and such other endorsements as may be by regulations required."],[0,"(f) Surrender of documents"],[0,"Each nonimmigrant shall present or surrender to the immigration officer at the port of entry such documents as may be by regulation required. In the case of an alien crewman not in possession of any individual documents other than a passport and until such time as it becomes practicable to issue individual documents, such alien crewman may be admitted, subject to the provisions of this part, if his name appears in the crew list of the vessel or aircraft on which he arrives and the crew list is visaed by a consular officer, but the consular officer shall have the right to deny admission to any alien crewman from the crew list visa."],[0,"(g) Nonissuance of visas or other documents"],[0,"No visa or other documentation shall be issued to an alien if (1) it appears to the consular officer, from statements in the application, or in the papers submitted therewith, that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law, (2) the application fails to comply with the provisions of this chapter, or the regulations issued thereunder, or (3) the consular officer knows or has reason to believe that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law: Provided, That a visa or other documentation may be issued to an alien who is within the purview of section 1182(a)(4) of this title, if such alien is otherwise entitled to receive a visa or other documentation, upon receipt of notice by the consular officer from the Attorney General of the giving of a bond or undertaking providing indemnity as in the case of aliens admitted under section 1183 of this title: Provided further, That a visa may be issued to an alien defined in section 1101(a)(15)(B) or (F) of this title, if such alien is otherwise entitled to receive a visa, upon receipt of a notice by the consular officer from the Attorney General of the giving of a bond with sufficient surety in such sum and containing such conditions as the consular officer shall prescribe, to insure that at the expiration of the time for which such alien has been admitted by the Attorney General, as provided in section 1184(a) of this title, or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States."],[0,"(h) Nonadmission upon arrival"],[0,"Nothing in this chapter shall be construed to entitle any alien, to whom a visa or other documentation has been issued, to be admitted 1 the United States, if, upon arrival at a port of entry in the United States, he is found to be inadmissible under this chapter, or any other provision of law. The substance of this subsection shall appear upon every visa application."],[0,"(i) Revocation of visas or documents"],[0,"After the issuance of a visa or other documentation to any alien, the consular officer or the Secretary of State may at any time, in his discretion, revoke such visa or other documentation. Notice of such revocation shall be communicated to the Attorney General, and such revocation shall invalidate the visa or other documentation from the date of issuance: Provided, That carriers or transportation companies, and masters, commanding officers, agents, owners, charterers, or consignees, shall not be penalized under section 1323(b) of this title for action taken in reliance on such visas or other documentation, unless they received due notice of such revocation prior to the alien's embarkation. There shall be no means of judicial review (including review pursuant to section 2241 of title 28 or any other habeas corpus provision, and sections 1361 and 1651 of such title) of a revocation under this subsection, except in the context of a removal proceeding if such revocation provides the sole ground for removal under section 1227(a)(1)(B) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1201?type=usc&year=mostrecent&link-type=html"},"by":{"0":"22, 22, 22, 19, 19","1":"3, 26, 40","2":"6, 7, 3"},"q":[{"src":"brief","b":0,"text":"the consular officer knows or has reason to believe","cite":"8 U.S.C. 1201(g)"},{"src":"brief","b":2,"text":"to an immigrant who has made proper application therefor.","cite":"8 U.S.C. 1201(a)(1)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(a)","(b)","(e)"],"by":{"0":"3, 7, 22, 22, 7, 22, 44"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(c)(1)"],"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"subparagraph (A) (other than clause (ii)).","cite":"8 U.S.C. 1225(c)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","by":{"0":"30"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5","1":"16","2":"3"}},{"t":"usc","label":"8 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/8/1361","stext":{"head":"§1361. Burden of proof upon alien","paras":[[0,"Whenever any person makes application for a visa or any other document required for entry, or makes application for admission, or otherwise attempts to enter the United States, the burden of proof shall be upon such person to establish that he is eligible to receive such visa or such document, or is not inadmissible under any provision of this chapter, and, if an alien, that he is entitled to the nonimmigrant, immigrant, special immigrant, immediate relative, or refugee status claimed, as the case may be. If such person fails to establish to the satisfaction of the consular officer that he is eligible to receive a visa or other document required for entry, no visa or other document required for entry shall be issued to such person, nor shall such person be admitted to the United States unless he establishes to the satisfaction of the Attorney General that he is not inadmissible under any provision of this chapter. In any removal proceeding under part IV of this subchapter against any person, the burden of proof shall be upon such person to show the time, place, and manner of his entry into the United States, but in presenting such proof he shall be entitled to the production of his visa or other entry document, if any, and of any other documents and records, not considered by the Attorney General to be confidential, pertaining to such entry in the custody of the Service. If such burden of proof is not sustained, such person shall be presumed to be in the United States in violation of law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1361?type=usc&year=mostrecent&link-type=html"},"by":{"0":"44","2":"7"},"q":[{"src":"brief","b":0,"text":"to the satisfaction of the consular officer,","cite":"8 U.S.C. 1361"}]},{"t":"usc","label":"8 U.S.C. § 1733","url":"https://www.law.cornell.edu/uscode/text/8/1733","by":{"0":"44"}},{"t":"usc","label":"6 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/6/236","subs":["(b)(1)","(c)(1)","(f)"],"stext":{"head":"§236. Visa issuance","paras":[[0,"(a) Definition"],[0,"In this subsection,1 the term \"consular office\" 2 has the meaning given that term under section 101(a)(9) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(9))."],[0,"(b) In general"],[0,"Notwithstanding section 104(a) of the Immigration and Nationality Act (8 U.S.C. 1104(a)) or any other provision of law, and except as provided in subsection (c) of this section, the Secretary—"],[1,"(1) shall be vested exclusively with all authorities to issue regulations with respect to, administer, and enforce the provisions of such Act [8 U.S.C. 1101 et seq.], and of all other immigration and nationality laws, relating to the functions of consular officers of the United States in connection with the granting or refusal of visas, and shall have the authority to refuse visas in accordance with law and to develop programs of homeland security training for consular officers (in addition to consular training provided by the Secretary of State), which authorities shall be exercised through the Secretary of State, except that the Secretary shall not have authority to alter or reverse the decision of a consular officer to refuse a visa to an alien; and"],[1,"(2) shall have authority to confer or impose upon any officer or employee of the United States, with the consent of the head of the executive agency under whose jurisdiction such officer or employee is serving, any of the functions specified in paragraph (1)."],[0,"(c) Authority of the Secretary of State"],[0,"(1) In general"],[1,"Notwithstanding subsection (b), the Secretary of State may direct a consular officer to refuse a visa to an alien if the Secretary of State deems such refusal necessary or advisable in the foreign policy or security interests of the United States."],[0,"(2) Construction regarding authority"],[1,"Nothing in this section, consistent with the Secretary of Homeland Security's authority to refuse visas in accordance with law, shall be construed as affecting the authorities of the Secretary of State under the following provisions of law:"],[2,"(A) Section 101(a)(15)(A) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(15)(A))."],[2,"(B) Section 204(d)(2) of the Immigration and Nationality Act (8 U.S.C. 1154) (as it will take effect upon the entry into force of the Convention on Protection of Children and Cooperation in Respect to Inter-Country adoption)."],[2,"(C) Section 212(a)(3)(B)(i)(IV)(bb) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(i)(IV)(bb))."],[2,"(D) Section 212(a)(3)(B)(i)(VI) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(i)(VI))."],[2,"(E) Section 212(a)(3)(B)(vi)(II) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(vi)(II))."],[2,"(F) Section 212(a)(3)(C) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(C))."],[2,"(G) Section 212(a)(10)(C) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(10)(C))."],[2,"(H) Section 212(f) of the Immigration and Nationality Act (8 U.S.C. 1182(f))."],[2,"(I) Section 219(a) of the Immigration and Nationality Act (8 U.S.C. 1189(a))."],[2,"(J) Section 237(a)(4)(C) of the Immigration and Nationality Act (8 U.S.C. 1227(a)(4)(C))."],[2,"(K) Section 401 of the Cuban Liberty and Democratic Solidarity (LIBERTAD) Act of 1996 [22 U.S.C. 6091]."],[2,"(L) Section 613 of the Departments of Commerce, Justice, and State, the Judiciary and Related Agencies Appropriations Act, 1999 3 (as contained in section 101(b) of division A of Public Law 105–277) (Omnibus Consolidated and Emergency Supplemental Appropriations Act, 1999); 112 Stat. 2681; H.R. 4328 (originally H.R. 4276) as amended by section 617 of Public Law 106–553."],[2,"(M) Section 103(f) of the Chemical Weapon Convention Implementation Act of 1998 [22 U.S.C. 6713(f)] (112 Stat. 2681–865)."],[2,"(N) Section 801 of H.R. 3427, the Admiral James W. Nance and Meg Donovan Foreign Relations Authorization Act, Fiscal Years 2000 and 2001 [8 U.S.C. 1182e], as enacted by reference in Public Law 106–113."],[2,"(O) Section 568 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 2002 (Public Law 107–115)."],[2,"(P) Section 51 of the State Department Basic Authorities Act of 1956 (22 U.S.C. 2723)."],[0,"(d) Consular officers and chiefs of missions"],[0,"(1) In general"],[1,"Nothing in this section may be construed to alter or affect—"],[2,"(A) the employment status of consular officers as employees of the Department of State; or"],[2,"(B) the authority of a chief of mission under section 207 of the Foreign Service Act of 1980 (22 U.S.C. 3927)."],[0,"(2) Construction regarding delegation of authority"],[1,"Nothing in this section shall be construed to affect any delegation of authority to the Secretary of State by the President pursuant to any proclamation issued under section 212(f) of the Immigration and Nationality Act (8 U.S.C. 1182(f)), consistent with the Secretary of Homeland Security's authority to refuse visas in accordance with law."],[0,"(e) Assignment of Homeland Security employees to diplomatic and consular posts"],[0,"(1) In general"],[1,"The Secretary is authorized to assign employees of the Department to each diplomatic and consular post at which visas are issued, unless the Secretary determines that such an assignment at a particular post would not promote homeland security."],[0,"(2) Functions"],[1,"Employees assigned under paragraph (1) shall perform the following functions:"],[2,"(A) Provide expert advice and training to consular officers regarding specific security threats relating to the adjudication of individual visa applications or classes of applications."],[2,"(B) Review any such applications, either on the initiative of the employee of the Department or upon request by a consular officer or other person charged with adjudicating such applications."],[2,"(C) Conduct investigations with respect to consular matters under the jurisdiction of the Secretary."],[0,"(3) Evaluation of consular officers"],[1,"The Secretary of State shall evaluate, in consultation with the Secretary, as deemed appropriate by the Secretary, the performance of consular officers with respect to the processing and adjudication of applications for visas in accordance with performance standards developed by the Secretary for these procedures."],[0,"(4) Report"],[1,"The Secretary shall, on an annual basis, submit a report to Congress that describes the basis for each determination under paragraph (1) that the assignment of an employee of the Department at a particular diplomatic post would not promote homeland security."],[0,"(5) Permanent assignment; participation in terrorist lookout committee"],[1,"When appropriate, employees of the Department assigned to perform functions described in paragraph (2) may be assigned permanently to overseas diplomatic or consular posts with country-specific or regional responsibility. If the Secretary so directs, any such employee, when present at an overseas post, shall participate in the terrorist lookout committee established under section 304 of the Enhanced Border Security and Visa Entry Reform Act of 2002 (8 U.S.C. 1733)."],[0,"(6) Training and hiring"],[0,"(A) In general"],[2,"The Secretary shall ensure, to the extent possible, that any employees of the Department assigned to perform functions under paragraph (2) and, as appropriate, consular officers, shall be provided the necessary training to enable them to carry out such functions, including training in foreign languages, interview techniques, and fraud detection techniques, in conditions in the particular country where each employee is assigned, and in other appropriate areas of study."],[0,"(B) Use of Center"],[2,"The Secretary is authorized to use the National Foreign Affairs Training Center, on a reimbursable basis, to obtain the training described in subparagraph (A)."],[0,"(7) Report"],[1,"Not later than 1 year after November 25, 2002, the Secretary and the Secretary of State shall submit to Congress—"],[2,"(A) a report on the implementation of this subsection; and"],[2,"(B) any legislative proposals necessary to further the objectives of this subsection."],[0,"(8) Effective date"],[1,"This subsection shall take effect on the earlier of—"],[2,"(A) the date on which the President publishes notice in the Federal Register that the President has submitted a report to Congress setting forth a memorandum of understanding between the Secretary and the Secretary of State governing the implementation of this section; or"],[2,"(B) the date occurring 1 year after November 25, 2002."],[0,"(f) No creation of private right of action"],[0,"Nothing in this section shall be construed to create or authorize a private right of action to challenge a decision of a consular officer or other United States official or employee to grant or deny a visa."],[0,"(g) Study regarding use of foreign nationals"],[0,"(1) In general"],[1,"The Secretary of Homeland Security shall conduct a study of the role of foreign nationals in the granting or refusal of visas and other documents authorizing entry of aliens into the United States. The study shall address the following:"],[2,"(A) The proper role, if any, of foreign nationals in the process of rendering decisions on such grants and refusals."],[2,"(B) Any security concerns involving the employment of foreign nationals."],[2,"(C) Whether there are cost-effective alternatives to the use of foreign nationals."],[0,"(2) Report"],[1,"Not later than 1 year after November 25, 2002, the Secretary shall submit a report containing the findings of the study conducted under paragraph (1) to the Committee on the Judiciary, the Committee on International Relations, and the Committee on Government Reform of the House of Representatives, and the Committee on the Judiciary, the Committee on Foreign Relations, and the Committee on Government 4 Affairs of the Senate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/236?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 5, 3, 5","1":"16","2":"4, 4"},"q":[{"src":"brief","b":0,"text":"private right of action to challenge a decision of a consular officer * * * to grant or deny a visa.","cite":"6 U.S.C. 236"}]},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"0":"2"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"0":"2"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"2"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"0":"2"}},{"t":"case","label":"Afroyim v. Rusk","cite":"387 U.S. 253","y":1967,"id":"1966/456","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"be shifted, canceled, or diluted at the will of the Federal Government, the States, or any other governmental unit.","cite":"387 U.S. 253, 262"}]},{"t":"case","label":"Aptheker v. Sec’y of State","cite":"378 U.S. 500","y":1964,"id":"1963/461","sc":1,"by":{"1":"37"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"But legislative history is not the law.","cite":"139 S. Ct. 1804, 1814"}]},{"t":"case","label":"Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"suggestions to authorize judicial review of visa denials.","cite":"511 U.S. 164, 187"}]},{"t":"case","label":"Barry v. Barchi","cite":"443 U.S. 55","y":1979,"id":"1978/77-803","sc":1,"by":{"1":"25"}},{"t":"case","label":"Bd. of Regents of State Colleges v. Roth","cite":"408 U.S. 564","y":1972,"id":"1971/71-162","sc":1,"by":{"1":"25"}},{"t":"case","label":"Bell v. Burson","cite":"402 U.S. 535","y":1971,"id":"1970/5586","sc":1,"by":{"1":"26, 27"}},{"t":"case","label":"Blanchard v. Bergeron","cite":"489 U.S. 87","y":1989,"id":"1988/87-1485","sc":1,"by":{"1":"18"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"1":"44"}},{"t":"case","label":"Bowen v. Michigan Academy of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"the strong presumption that Congress intends judicial review of administrative action.","cite":"476 U.S. 667, 670"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"strong presumption that Congress intends judicial review of administrative action.","cite":"476 U. S. 667, 670"}]},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"by":{"1":"15"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"by":{"1":"17"}},{"t":"case","label":"Douglas v. Buder","cite":"412 U.S. 430","y":1973,"id":"1972/72-6198","sc":1,"by":{"1":"42"}},{"t":"case","label":"Flemming v. Nestor","cite":"363 U.S. 603","y":1960,"id":"1959/54","sc":1,"by":{"1":"28"}},{"t":"case","label":"Frost v. R.R. Comm’n of State of Cal.","cite":"271 U.S. 583","y":1926,"id":"scdb/1925-198","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"If the state may compel the surrender of one constitutional right as a condition of its favor, it may, in like manner, compel a surrender of all. It is inconceivable that guarantees embedded in the Constitution of the United States may thus be manipulated out of existence.","cite":"271 U.S. 583, 593-94"}]},{"t":"case","label":"Garrity v. New Jersey","cite":"385 U.S. 493","y":1967,"id":"1966/13","sc":1,"by":{"1":"37"}},{"t":"case","label":"Gegiow v. Uhl","cite":"239 U.S. 3","y":1915,"id":"scdb/1915-065","sc":1,"by":{"1":"41"}},{"t":"case","label":"Goldberg v. Kelly","cite":"397 U.S. 254","y":1970,"id":"1969/62","sc":1,"by":{"1":"26"}},{"t":"case","label":"Goss v. Lopez","cite":"419 U.S. 565","y":1975,"id":"1974/73-898","sc":1,"by":{"1":"26"}},{"t":"case","label":"Greenholtz v. Inmates of Neb. Penal & Correctional Complex","cite":"442 U.S. 1","y":1979,"id":"1978/78-201","sc":1,"by":{"1":"26, 42"}},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"‘it brings the old soil with it.’","cite":"584 U.S. 59, 73"}]},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"by":{"1":"42"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"by":{"1":"14"}},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"by":{"1":"41"}},{"t":"case","label":"Ky. Dep’t of Corrections v. Thompson","cite":"490 U.S. 454","y":1989,"id":"1988/87-1815","sc":1,"by":{"1":"41"}},{"t":"case","label":"Kwong Hai Chew v. Colding","cite":"344 U.S. 590","y":1953,"id":"scdb/1952-047","sc":1,"by":{"1":"14"}},{"t":"case","label":"Lem Moon Sing v. United States","cite":"158 U.S. 538","y":1895,"id":"scdb/1894-233","sc":1,"by":{"1":"16"}},{"t":"case","label":"Logan v. Zimerman Brush Co.","cite":"455 U.S. 422","y":1982,"id":"1981/80-5950","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"relating to the whole domain of social and economic fact","cite":"455 U.S. 422, 430"}]},{"t":"case","label":"Loving v. Commonwealth","cite":"206 Va. 924","y":1966,"court":"Va.","url":"https://www.courtlistener.com/c/Va./206/924/","by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"was their cohabitation as man and wife","cite":"206 Va. 924, 930"}]},{"t":"case","label":"Loving v. Virginia","cite":"388 U.S. 1","y":1967,"id":"1966/395","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"cannot be infringed by the State.","cite":"388 U.S. at 12"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"[m]arriage is one of the `basic civil rights of man,' fundamental to our very existence and survival.","cite":"388 U. S. 1, 12"}]},{"t":"case","label":"Ludecke v. U.S. Marshal","cite":"15 F.3d 496","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/15/496/","by":{"1":"40"}},{"t":"case","label":"Lutwak v. United States","cite":"344 U.S. 604","y":1953,"id":"scdb/1952-048","sc":1,"by":{"1":"31"}},{"t":"case","label":"Mackenzie v. Hare","cite":"239 U.S. 299","y":1915,"id":"scdb/1915-022","sc":1,"by":{"1":"23","2":"10"}},{"t":"case","label":"Marcello v. Bonds","cite":"349 U.S. 302","y":1955,"id":"scdb/1954-086","sc":1,"by":{"1":"17"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"by":{"1":"17"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"by":{"1":"37, 43","2":"15"},"q":[{"src":"argument","who":"Mr. Lee","text":"The regulations refer to that as a standard which is akin to probable cause. So we think, under a Mathews-Eldridge analysis, the risk of arbitrary deprivations and along with the --"},{"src":"argument","who":"Justice Kavanaugh","text":"-- that's what you're trying to do, is replace Mandel and the Justice Kennedy concurrence and Trump versus Hawaii with a Mathews v. Eldridge test, which would then in turn as you would apply it require substantially more process than our precedents have previously required."},{"src":"argument","who":"Justice Barrett","text":"And your weighing, I take it, is probably coming from Mathews versus Eldridge, which I don't think is the standard here. So where do we get the constitutional right to an opportunity to be heard in this Mandel context?"}]},{"t":"case","label":"Memphis Light, Gas & Water Div. v. Craft","cite":"436 U.S. 1","y":1978,"id":"1977/76-39","sc":1,"by":{"1":"25, 26"}},{"t":"case","label":"Meyer v. Nebraska","cite":"262 U.S. 390","y":1923,"id":"1900-1940/262us390","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"establish a home and bring up children,","cite":"262 U.S. 390, 399"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"long recognized at common law as essential to the orderly pursuit of happiness by free men.","cite":"262 U. S. 390, 399"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"to marry, establish a home and bring up children","cite":"262 U. S., at 399"},{"src":"argument","who":"Justice Sotomayor","text":"That's our Meyer case. In Loving versus Virginia, we said marriage is fundamental. In United States versus Windsor, we said \"marriage is more than a routine classification for purposes of certain statutory benefits.\" So -- and Obergefell, I'm not going to cite it, but it said something to that effect."},{"src":"argument","who":"Mr. Lee","text":"And in a number of the other substantive due process cases, Meyer, for example, which acknowledged the substantive right to raise a family and establish a home, which certainly has a cohabitational element, in Smith against the Foster Families Organization, the issue of the right to daily personal intimate association was recognized by this Court as a substantive right."}]},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"by":{"1":"17"}},{"t":"case","label":"Miller v. Albright","cite":"523 U.S. 420","y":1998,"id":"1997/96-1060","sc":1,"by":{"1":"13, 15"}},{"t":"case","label":"Moore v. City of East Cleveland","cite":"431 U.S. 494","y":1977,"id":"1976/75-6289","sc":1,"by":{"1":"20"}},{"t":"case","label":"Morfin v. Tillerson","cite":"851 F.3d 710","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/851/710/","by":{"1":"49"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"by":{"1":"26, 28"}},{"t":"case","label":"Mullane v. Cent. Hanover Bank & Trust Co.","cite":"339 U.S. 306","y":1950,"id":"scdb/1949-066","sc":1,"by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"reasonably calculated . . . to apprise interested parties of the pendency of the action and afford them an opportunity to present their objections.","cite":"339 U.S. 306, 314"},{"src":"argument","who":"Mr. Lee","text":"Mu�oz to guess at the reason for the denial and provided only a mere gesture at due process, which this Court said was insufficient in Mullane."},{"src":"argument","who":"Justice Barrett","text":"Mandel talks about notice and giving you the basis, but it doesn't talk about Mullane and an opportunity to be heard. And your weighing, I take it, is probably coming from Mathews versus Eldridge, which I don't think is the standard here."}]},{"t":"case","label":"Olim v. Wakinekona","cite":"461 U.S. 238","y":1983,"id":"1982/81-1581","sc":1,"by":{"1":"42"}},{"t":"case","label":"Oyama v. California","cite":"332 U.S. 633","y":1948,"id":"scdb/1947-025","sc":1,"by":{"1":"35"}},{"t":"case","label":"Paul v. Davis","cite":"424 U.S. 693","y":1976,"id":"1975/74-891","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"a variety of interests which are difficult of definition but are nevertheless comprehended within the meaning of either ‘liberty’ or ‘property’ as meant in the Due Process Clause.","cite":"424 U.S. 693, 710"}]},{"t":"case","label":"Perry v. Sindermann","cite":"408 U.S. 593","y":1972,"id":"1971/70-36","sc":1,"by":{"1":"27"}},{"t":"case","label":"Procunier v. Martinez","cite":"416 U.S. 396","y":1974,"id":"1973/72-1465","sc":1,"by":{"1":"34, 40","2":"13"},"q":[{"src":"brief","b":1,"text":"[T]he interests of both parties are inextricably meshed. The wife of a prison inmate who is not permitted to read all that her husband wanted to say to her has suffered an abridgment of her interest in communicating with him as plain as that which results from censorship of her letter to him.","cite":"416 U.S. 396, 409"}]},{"t":"case","label":"Prushinowski v. Samples","cite":"734 F.2d 1016","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/734/1016/","by":{"1":"40"}},{"t":"case","label":"Purkett v. Elem","cite":"514 U.S. 765","y":1995,"id":"1994/94-802","sc":1,"by":{"1":"39"}},{"t":"case","label":"Reno v. Catholic Social Services, Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"by":{"1":"18"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"by":{"1":"39"}},{"t":"case","label":"Roberts v. U.S. Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"not only a special community of thoughts, experiences, and beliefs but also distinctively personal aspects of one’s life.","cite":"468 U.S. 609, 619-20"}]},{"t":"case","label":"Rocha v. INS","cite":"450 F.2d 946","y":1971,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/450/946/","by":{"1":"23"}},{"t":"case","label":"Rusk v. Cort","cite":"369 U.S. 367","y":1962,"id":"scdb/1961-054","sc":1,"by":{"1":"15"}},{"t":"case","label":"Saenz v. Roe","cite":"526 U.S. 489","y":1999,"id":"1998/98-97","sc":1,"by":{"1":"35"}},{"t":"case","label":"Sale v. Haitian Centers Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"by":{"1":"15"}},{"t":"case","label":"Schware v. Board of Bar Examiners","cite":"353 U.S. 232","y":1957,"id":"1956/92","sc":1,"by":{"1":"42"}},{"t":"case","label":"Simmons v. United States","cite":"390 U.S. 377","y":1968,"id":"1967/55","sc":1,"by":{"1":"36"}},{"t":"case","label":"Smith v. Goguen","cite":"415 U.S. 566","y":1974,"id":"1973/72-1254","sc":1,"by":{"1":"48"}},{"t":"case","label":"Smith v. Org. of Foster Families","cite":"431 U.S. 816","y":1977,"id":"1976/76-180","sc":1,"by":{"1":"19, 21"},"q":[{"src":"brief","b":1,"text":"[T]he importance of the familial relationship, to the individuals involved and to the society, stems from the emotional attachments that derive from the intimacy of daily association.","cite":"431 U.S. at 844"},{"src":"argument","who":"Mr. Lee","text":"And in a number of the other substantive due process cases, Meyer, for example, which acknowledged the substantive right to raise a family and establish a home, which certainly has a cohabitational element, in Smith against the Foster Families Organization, the issue of the right to daily personal intimate association was recognized by this Court as a substantive right."}]},{"t":"case","label":"Superintendent, Mass. Correctional Institution v. Hill","cite":"472 U.S. 445","y":1985,"id":"1984/84-438","sc":1,"by":{"1":"42"}},{"t":"case","label":"Travers v. Reinhardt","cite":"205 U.S. 423","y":1907,"id":"scdb/1906-110","sc":1,"by":{"1":"21"}},{"t":"case","label":"Tsoi Sim v. United States","cite":"116 F. 920","y":1902,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F./116/920/","by":{"1":"22"}},{"t":"case","label":"Turner v. Safley","cite":"482 U.S. 78","y":1987,"id":"1986/85-1384","sc":1,"by":{"1":"34"}},{"t":"case","label":"U.S. ex rel. Accardi v. Shaughnessy","cite":"347 U.S. 260","y":1954,"id":"1940-1955/347us260","sc":1,"by":{"1":"29"}},{"t":"case","label":"U.S. ex rel. Vajtauer v. Comm’r of Immigration","cite":"273 U.S. 103","y":1927,"id":"scdb/1926-142","sc":1,"by":{"1":"42"}},{"t":"case","label":"United States v. Gue Lim","cite":"176 U.S. 459","y":1900,"id":"scdb/1899-133","sc":1,"by":{"1":"22","2":"11"}},{"t":"case","label":"United States v. Reynolds","cite":"345 U.S. 1","y":1953,"id":"1940-1955/345us1","sc":1,"by":{"1":"46"}},{"t":"case","label":"United States v. Wong Kim Ark","cite":"169 U.S. 649","y":1898,"id":"1850-1900/169us649","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"The Fourteenth Amendment, while it leaves the power, where it was before, in Congress, to regulate naturalization, has conferred no authority upon Congress to restrict the effect of birth, declared by the Constitution to constitute a sufficient and complete right to citizenship.","cite":"169 U.S. 649, 703"}]},{"t":"case","label":"Vitek v. Jones","cite":"445 U.S. 480","y":1980,"id":"1979/78-1155","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"a right or expectation that adverse action will not be taken against [her] except upon the occurrence of specified behavior, ‘the determination of whether such behavior has occurred becomes critical, and the minimum requirements of procedural due process appropriate for the circumstances must be observed.’","cite":"445 U.S. 480, 491"},{"src":"argument","who":"Mr. Lee","text":"And -- and I think the Court has addressed a similar context in the prison-type cases, Vitek against Jones, Harper against Washington, where the Court recognized an underlying substantive constitutional interest, for example, in not being forced to take psychotropic drugs or not being removed to a mental facility, and yet it -- the way it balanced those interests was by providing a minimal level of procedural due process."}]},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"by":{"1":"34"}},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"by":{"1":"26, 27, 42"}},{"t":"case","label":"Wood v. Allen","cite":"558 U.S. 290","y":2010,"id":"2009/08-9156","sc":1,"by":{"1":"14"}},{"t":"case","label":"Yee v. Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"1":"14"}},{"t":"case","label":"Zyapkov v. Lynch","cite":"817 F.3d 556","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/817/556/","by":{"1":"31"}},{"t":"usc","label":"5 U.S.C. § 559","url":"https://www.law.cornell.edu/uscode/text/5/559","by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"except to the extent that it does so expressly.","cite":"5 U.S.C. § 559"}]},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","subs":["(1)"],"stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"by":{"1":"17","2":"4"}},{"t":"usc","label":"8 U.S.C. § 1183a","url":"https://www.law.cornell.edu/uscode/text/8/1183a","subs":["(a)(1)","(a)(1)(B)","(a)(1)(C)","(d)(1)","(d)(2)"],"by":{"1":"5, 28, 5, 28, 31, 5, 5, 5"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(b)(1)"],"by":{"1":"4"}},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","subs":["(c)"],"by":{"1":"31"}},{"t":"usc","label":"8 U.S.C. § 1534","url":"https://www.law.cornell.edu/uscode/text/8/1534","subs":["(e)(3)(B)"],"by":{"1":"45"}},{"t":"usc","label":"18 U.S.C. § 1546","url":"https://www.law.cornell.edu/uscode/text/18/1546","by":{"1":"31"}},{"t":"usc","label":"31 U.S.C. § 9701","url":"https://www.law.cornell.edu/uscode/text/31/9701","by":{"1":"44"}},{"t":"law","label":"Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"1":"24"}},{"t":"reg","label":"8 C.F.R. § 103.2","url":"https://www.ecfr.gov/current/title-8/section-103.2","subs":["(a)","(b)","(b)(6)","(b)(16)"],"by":{"1":"30, 3, 30, 44, 46"}},{"t":"reg","label":"8 C.F.R. § 205.1","url":"https://www.ecfr.gov/current/title-8/section-205.1","subs":["(a)(3)"],"by":{"1":"32"}},{"t":"reg","label":"8 C.F.R. § 212.7","url":"https://www.ecfr.gov/current/title-8/section-212.7","subs":["(e)(14)(i)"],"by":{"1":"4, 27"}},{"t":"reg","label":"22 C.F.R. § 40.6","url":"https://www.ecfr.gov/current/title-22/section-40.6","by":{"1":"40, 41"},"q":[{"src":"brief","b":1,"text":"require[s] a determination based upon facts or circumstances which would lead a reasonable person to conclude that the applicant is ineligible to receive a visa,","cite":"22 C.F.R. § 40.6"},{"src":"brief","b":1,"text":"A visa can be refused only upon a ground specifically set out in the law or implementing regulations.","cite":"22 C.F.R. § 40.6"}]},{"t":"reg","label":"22 C.F.R. § 42.43","url":"https://www.ecfr.gov/current/title-22/section-42.43","subs":["(a)"],"by":{"1":"31"}},{"t":"reg","label":"22 C.F.R. § 42.81","url":"https://www.ecfr.gov/current/title-22/section-42.81","subs":["(b)","(e)"],"by":{"1":"29, 47, 6, 29, 38, 41, 43, 47"}},{"t":"reg","label":"Provisional Unlawful Presence Waivers of Inadmissibility for Certain Immediate Relatives, 78 Fed. Reg. 536","url":"https://www.govinfo.gov/link/fr/78/536","by":{"1":"4, 27","2":"8"}},{"t":"reg","label":"Expansion of Provisional Unlawful Presence Waivers of Inadmissibility, 81 Fed. Reg. 50244","url":"https://www.govinfo.gov/link/fr/81/50244","by":{"1":"4, 5","2":"8"}},{"t":"reg","label":"Schedule of Fees for Consular Services, 86 Fed. Reg. 74018","url":"https://www.govinfo.gov/link/fr/86/74018","by":{"1":"44"}},{"t":"case","label":"Allen v. Milas","cite":"896 F.3d 1094","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/1094/","by":{"2":"4"}},{"t":"case","label":"Baldwin v. Reese","cite":"541 U.S. 27","y":2004,"id":"2003/02-964","sc":1,"by":{"2":"15"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"determined not only from [a statute’s] express language, but also from the structure of the statutory scheme, its objectives, its legislative history, and the nature of the administrative action involved.","cite":"467 U.S. 340, 345"}]},{"t":"case","label":"Meachum v. Fano","cite":"427 U.S. 215","y":1976,"id":"1975/75-252","sc":1,"by":{"2":"12, 13"}},{"t":"case","label":"Orloff v. Willoughby","cite":"345 U.S. 83","y":1953,"id":"scdb/1952-059","sc":1,"by":{"2":"13"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"23"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)"],"by":{"2":"4, 4"},"q":[{"src":"brief","b":2,"text":"to the extent that * * * statutes preclude judicial review,","cite":"5 U.S.C. 701(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/8/1152","subs":["(a)(4)"],"by":{"2":"14"}},{"t":"reg","label":"3 C.F.R. pt. 720","url":"https://www.ecfr.gov/current/title-3/part-720","by":{"2":"21"}}]};